import{_ as t,a as i,b as a,c as r,d as o,e,f as n,g as s,h as d,i as h,j as u,k as p,l as g,m as c,n as _,o as b,p as q}from"./chunks/image17.BHgKT67r.js";import{_ as m,o as k,c as f,ag as x}from"./chunks/framework.D9ghT4bC.js";const $=JSON.parse('{"title":"众神与国王入门指南","description":"","frontmatter":{"title":"众神与国王入门指南"},"headers":[],"relativePath":"zh/Community/Guides/Gods-and-Kings-guide/index.md","filePath":"zh/Community/Guides/Gods-and-Kings-guide/index.md"}'),P={name:"zh/Community/Guides/Gods-and-Kings-guide/index.md"};function v(G,l,U,z,C,S){return k(),f("div",null,[...l[0]||(l[0]=[x('<h1 id="众神与国王入门指南" tabindex="-1">众神与国王入门指南 <a class="header-anchor" href="#众神与国王入门指南" aria-label="Permalink to &quot;众神与国王入门指南&quot;">​</a></h1><blockquote><p>作者：恶</p><p>编辑：SpringPizazz</p><p>完稿日期：2024年2月19日</p><p>游戏版本：4.16.0</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>鉴于新手可能难以理解 Lance 的教程，我计划亲自撰写一部 Unciv 的基础入门指南。我相信，只要萌新对游戏有基本的认识，他们就能够理解 Lance 的早期战争策略教程。但为了进一步提升新人的游戏技巧，我特别制作了这份基础教学材料，旨在帮助每一位新玩家都能对游戏有深入的理解。</p><h2 id="_1-基本产出" tabindex="-1">1 基本产出 <a class="header-anchor" href="#_1-基本产出" aria-label="Permalink to &quot;1 基本产出&quot;">​</a></h2><p><img src="'+t+'" alt="基本产出"></p><blockquote><p>注：本章为基础内容，主要针对新手玩家。资深玩家可选择跳过。</p></blockquote><p>在游戏界面的右上角，你会看到一系列重要的数值指标，它们从左到右依次为：<strong>产能 / 锤</strong>、<strong>食物 / 粮</strong>、<strong>金钱 / 金</strong>、<strong>科研 / 瓶</strong>、 <strong>文化 / 琴</strong>、<strong>信仰 / 鸽</strong>。</p><h3 id="_1-1-产能" tabindex="-1">1.1 产能 <a class="header-anchor" href="#_1-1-产能" aria-label="Permalink to &quot;1.1 产能&quot;">​</a></h3><p>产能在 Unciv 游戏中占据着至关重要的地位，它是建造移民、工人、各类建筑物以及军事单位的基础。</p><p>以工人为例，若一个工人的建造需求为 46 产能，而某座城市每回合能提供 6 产能，那么仅需 8 回合便能顺利完成一个工人的建造。</p><p>然而，在实际建造过程中，产能往往不会与建造需求完美匹配，因此经常会出现产能溢出的现象。这些溢出的产能并不会浪费，而是会累积并继承到下一个建造单位或建筑中。同理，食物的运作机制亦是如此，多余的食物也会为后续的建造或人口增长提供储备。</p><h3 id="_1-2-食物" tabindex="-1">1.2 食物 <a class="header-anchor" href="#_1-2-食物" aria-label="Permalink to &quot;1.2 食物&quot;">​</a></h3><p>食物在 Unciv 游戏中是第二重要的数值，它直接决定了人口的增长速度。而人口不仅仅是一个数字，它与多个游戏要素紧密相连。</p><ul><li>每个人口都能为贡献 1 点科研，这意味着人口的增长也间接推动了科技的进步。</li><li>当商路建立后，每座分城中的每个人口都会为所在城市的贸易路线增加约 1 点金钱，使得食物间接地对经济发展产生了积极影响。</li><li>在军事方面，人口越多，城市的防御能力就越强，这有助于抵御外敌的入侵。同时，人口还能提高补给能力。在游戏中，所有单位都需要补给，而超出补给范围将会受到产能惩罚。</li></ul><p><img src="'+i+'" alt="食物增长"></p><p>然而，食物的增长并不是无限的。当城市的<strong>快乐</strong>降低时，每座城市的食物收益将减少 75%，这极大地减缓了人口的增长速度。在游戏前期，快乐往往较为稀缺，这使得人口无法持续快速增长。</p><p>此外，随着城市人口的增加，增长所需的食物也越来越多。这导致在早期战争阶段，通常当主城人口达到 6 人、分城人口达到 4 或 5 人时，玩家就需要转变策略，将重心转向提高产能。因为继续增加人口所需的食物成本太高，与纯产能收益不成正比。</p><h3 id="_1-3-金钱" tabindex="-1">1.3 金钱 <a class="header-anchor" href="#_1-3-金钱" aria-label="Permalink to &quot;1.3 金钱&quot;">​</a></h3><p>在 Unciv 游戏中，金钱是一个不可忽视的数值，它在多个方面发挥着重要作用：</p><ul><li>可用于升级兵种，这是提升军事力量的关键途径之一。</li><li>可用于购买单位、建筑或地块，以加速文明的发展和扩张。</li><li>在文明交易和成为城邦宗主国的过程中扮演重要角色。</li></ul><p>然而，在游戏前期，金钱的作用可能并不明显，但这并不意味着可以忽视它。如果玩家在游戏初期没有囤积足够的金钱（例如至少 100 金），以支撑到市场科技的研发，就可能会面临严重的发育困境。</p><p>当金钱变为负数时，游戏将进入一个极具挑战性的阶段：</p><ul><li>每回合的负回合金将减少科研值，严重影响科技进程。</li><li>当金钱减少到 -200 时，游戏将自动解散玩家的一个单位，这是对玩家实力的重大打击。</li></ul><p>因此，玩家需要精心管理金钱，确保在关键时刻拥有足够的资金支持。</p><h3 id="_1-4-科研" tabindex="-1">1.4 科研 <a class="header-anchor" href="#_1-4-科研" aria-label="Permalink to &quot;1.4 科研&quot;">​</a></h3><p>科研用于解锁科技，通常看地形选择要点的科技树。</p><h3 id="_1-5-文化" tabindex="-1">1.5 文化 <a class="header-anchor" href="#_1-5-文化" aria-label="Permalink to &quot;1.5 文化&quot;">​</a></h3><p>文化用于解锁文化政策和扩张城市地块。例如，城市文化圈包揽的马地块，1 回合后扩张。</p><h3 id="_1-6-快乐" tabindex="-1">1.6 快乐 <a class="header-anchor" href="#_1-6-快乐" aria-label="Permalink to &quot;1.6 快乐&quot;">​</a></h3><p>快乐在 Unciv 游戏中是一个重要的指标，它对于文明的发展和繁荣起着关键的作用。</p><ul><li>当快乐值积累到一定程度时，玩家可以开启<strong>黄金时代</strong>，带来各种增益。</li><li>提高快乐值的方式包括开发奢侈地块和修建快乐建筑。</li></ul><p>负面影响：</p><ul><li>快乐 ≤ 0 → 食物收益减少 75%。</li><li>快乐 &lt; -10 → 产能减少 50%。</li></ul><p>因此，玩家需密切关注快乐值变化，并采取有效措施维持正值。</p><h3 id="_1-7-信仰" tabindex="-1">1.7 信仰 <a class="header-anchor" href="#_1-7-信仰" aria-label="Permalink to &quot;1.7 信仰&quot;">​</a></h3><p>信仰影响宗教发展和特殊能力解锁。</p><ul><li>要产生万神殿，需累积一定信仰值，且每次新建万神殿所需信仰递增。</li><li>早期信仰主要来自<strong>寺庙</strong>（26 产能 + 1 维护费），但回报周期长（至少 10 回合）。</li></ul><p>与其他早期投资对比：</p><ul><li><strong>工匠</strong>：前 10 回合无回报，但长期产能高。</li><li><strong>粮仓</strong>：返还快，但受地块和快乐限制。</li><li><strong>移民</strong>：建新城可快速返还投入，提供补给和军事能力，但可能降低快乐。</li></ul><p>尽管寺庙早期回报慢，但部分万神殿对长期发展帮助大。<strong>推荐早战万神殿</strong>：</p><ul><li>天空之神（+文化）</li><li>工匠之神（+产能）</li><li>沙漠民俗（+信仰）</li><li>主神纪念碑（加速奇观）</li></ul><h3 id="_1-8-本章总结" tabindex="-1">1.8 本章总结 <a class="header-anchor" href="#_1-8-本章总结" aria-label="Permalink to &quot;1.8 本章总结&quot;">​</a></h3><p>本章详细阐述了 Unciv 游戏中的六大基础数值——产能、食物、金钱、科研、文化和信仰的各自作用及其潜在的负面影响。同时，深入探讨了这些数值之间的相互关系及其独特特点。此外，还特别介绍了一个与这些数值紧密相连的关键因素——<strong>人口</strong>，它在游戏中扮演着举足轻重的角色，对玩家的战略决策和文明发展具有深远的影响。</p><h2 id="_2-地形、地貌与资源" tabindex="-1">2 地形、地貌与资源 <a class="header-anchor" href="#_2-地形、地貌与资源" aria-label="Permalink to &quot;2 地形、地貌与资源&quot;">​</a></h2><blockquote><p>该部分建议结合地图编辑器使用。</p></blockquote><h3 id="_2-1-地形与地貌" tabindex="-1">2.1 地形与地貌 <a class="header-anchor" href="#_2-1-地形与地貌" aria-label="Permalink to &quot;2.1 地形与地貌&quot;">​</a></h3><p>地形分为<strong>崎岖</strong>（森林、丘陵、丛林）和<strong>平地</strong>（草原、沙漠、海洋等）。</p><ul><li>单位在崎岖地形移动消耗 2 点移动力，平地消耗 1 点。</li><li><strong>沼泽</strong>是特例：属平地，但移动消耗 3 点。</li><li><strong>湖泊</strong>：内陆海洋地形，船运陆军战斗力大幅下降，可视为天然屏障。</li></ul><p>地形改造：</p><ul><li>工人可砍伐森林/丛林/沼泽（需科技）。</li><li>砍伐树林提供一次性产出，优先级： <ul><li>境内 1–2 环：20 产能</li><li>境内 3 环：15 产能</li><li>境外 2 环：13 产能</li><li>境外 3 环：10 产能</li><li>境外 ≥4 环：7 产能</li></ul></li></ul><h4 id="视野" tabindex="-1">视野 <a class="header-anchor" href="#视野" aria-label="Permalink to &quot;视野&quot;">​</a></h4><p><img src="'+a+'" alt="视野"></p><ul><li>所有单位早期视野为 2 格。</li><li>视野受地形高度影响：<strong>山脉 &gt; 丘陵 &gt; 平地</strong>。 <ul><li>低处单位无法看到高处背后地块。</li><li>森林虽无高度加成，但会阻挡同高度视野。</li></ul></li><li><strong>冷知识</strong>：站在山脉上视野等同于平地（设计特性）。</li><li>若视野外一格比自身高且中间无同级阻挡，也能看见。</li></ul><p><img src="'+r+'" alt="视野示例1"><img src="'+o+'" alt="视野示例2"></p><h3 id="_2-2-河流" tabindex="-1">2.2 河流 <a class="header-anchor" href="#_2-2-河流" aria-label="Permalink to &quot;2.2 河流&quot;">​</a></h3><p>河流位于两个地块之间，提供：</p><ul><li>+1 金钱</li><li>淡水资源</li></ul><p>战略价值：</p><ul><li>单位过河消耗全部移动力。</li><li>近战单位攻击河对岸单位时，战斗力 -20%。</li><li>构成天然防御屏障。</li></ul><h3 id="_2-3-资源" tabindex="-1">2.3 资源 <a class="header-anchor" href="#_2-3-资源" aria-label="Permalink to &quot;2.3 资源&quot;">​</a></h3><p>资源分三类：</p><h4 id="奖金资源" tabindex="-1">奖金资源 <a class="header-anchor" href="#奖金资源" aria-label="Permalink to &quot;奖金资源&quot;">​</a></h4><ul><li>仅提供粮食和产能。</li><li><strong>野鹿、小麦</strong>是前期重点，配合<strong>粮仓</strong>可获额外食物加成。</li></ul><h4 id="奢侈资源" tabindex="-1">奢侈资源 <a class="header-anchor" href="#奢侈资源" aria-label="Permalink to &quot;奢侈资源&quot;">​</a></h4><ul><li>每种提供 <strong>4 点快乐</strong>（重复无效）。</li><li>特殊： <ul><li><strong>盐</strong>：开发后 +1 资源产出。</li><li><strong>大理石</strong>：建造奇观加速 15%（不可叠加）。</li></ul></li></ul><h4 id="战略资源" tabindex="-1">战略资源 <a class="header-anchor" href="#战略资源" aria-label="Permalink to &quot;战略资源&quot;">​</a></h4><ul><li>用于军事单位生产/升级。</li><li><strong>马</strong>是前期核心： <ul><li>可建马戏场（+快乐）</li><li>是战车射手必需资源。</li></ul></li></ul><blockquote><p>资源数量决定发育速度。选城址应尽量靠近各类资源。</p></blockquote><h2 id="_3-早期作战" tabindex="-1">3 早期作战 <a class="header-anchor" href="#_3-早期作战" aria-label="Permalink to &quot;3 早期作战&quot;">​</a></h2><p><img src="'+e+'" alt="早期作战"></p><p>前期军事行动目的：<strong>探图、抢地、骚扰</strong>。</p><h3 id="_3-1-探图" tabindex="-1">3.1 探图 <a class="header-anchor" href="#_3-1-探图" aria-label="Permalink to &quot;3.1 探图&quot;">​</a></h3><p>目的：</p><ul><li>寻找合适分城位置（资源丰富、易守难攻、支援快）。</li><li>探明敌方城市位置。</li></ul><blockquote><p>丘陵城市比平原多 5 点城防 +1 产能，优先选丘陵建分城。</p></blockquote><h3 id="_3-2-抢地" tabindex="-1">3.2 抢地 <a class="header-anchor" href="#_3-2-抢地" aria-label="Permalink to &quot;3.2 抢地&quot;">​</a></h3><ul><li>移民是高投资高回报单位，越早越好。</li><li>关键点位常引发争夺。</li><li>注意敌方单位控制区（ZOC），避免额外移动力消耗。</li></ul><p><img src="'+n+'" alt="控制区"></p><h3 id="_3-3-骚扰" tabindex="-1">3.3 骚扰 <a class="header-anchor" href="#_3-3-骚扰" aria-label="Permalink to &quot;3.3 骚扰&quot;">​</a></h3><ul><li>干扰敌方发展。</li><li>削弱其实力。</li><li>创造进攻机会（如小股袭击、破坏资源点）。</li></ul><h3 id="_3-4-本章总结" tabindex="-1">3.4 本章总结 <a class="header-anchor" href="#_3-4-本章总结" aria-label="Permalink to &quot;3.4 本章总结&quot;">​</a></h3><p>早期军事行动围绕探图、抢地、骚扰展开，合理规划可奠定优势。</p><h2 id="_4-早期种田" tabindex="-1">4 早期种田 <a class="header-anchor" href="#_4-早期种田" aria-label="Permalink to &quot;4 早期种田&quot;">​</a></h2><h3 id="_4-1-工人" tabindex="-1">4.1 工人 <a class="header-anchor" href="#_4-1-工人" aria-label="Permalink to &quot;4.1 工人&quot;">​</a></h3><p>工人是高投入高回报单位，功能包括：</p><ul><li><strong>砍伐森林/雨林</strong>：爆发产能（见下表）。</li><li><strong>开发奢侈资源</strong>（快乐不足时）。</li><li><strong>开发战略资源</strong>（快乐充足时，如马、铁）。</li></ul><table tabindex="0"><thead><tr><th>砍伐对象</th><th>是否在境内</th><th>与最近市中心距离</th><th>爆发产能</th></tr></thead><tbody><tr><td>森林</td><td>是</td><td>1</td><td>30</td></tr><tr><td>森林</td><td>是</td><td>2</td><td>30</td></tr><tr><td>森林</td><td>是</td><td>3</td><td>22</td></tr><tr><td>森林</td><td>是</td><td>4</td><td>15</td></tr><tr><td>森林</td><td>否</td><td>1</td><td>22</td></tr><tr><td>森林</td><td>否</td><td>2</td><td>20</td></tr><tr><td>森林</td><td>否</td><td>3</td><td>15</td></tr><tr><td>森林</td><td>否</td><td>4</td><td>10</td></tr><tr><td>丛林</td><td>无所谓</td><td>无所谓</td><td>0</td></tr></tbody></table><blockquote><p>丛林砍伐不提供产能。</p></blockquote><h3 id="_4-2-控产" tabindex="-1">4.2 控产 <a class="header-anchor" href="#_4-2-控产" aria-label="Permalink to &quot;4.2 控产&quot;">​</a></h3><p><img src="'+s+'" alt=""></p><p>“控产”指手动控制城市人口工作地块。</p><ul><li>自动分配优先食物，但在<strong>负快乐</strong>下食物收益 -75%，仍选食物会导致内政收益低。</li><li><strong>解决方案</strong>：手动锁定高产能地块，只要食物够维持人口不饿死即可。</li><li>操作：双击地块即可锁定。</li></ul><h3 id="_4-3-基建" tabindex="-1">4.3 基建 <a class="header-anchor" href="#_4-3-基建" aria-label="Permalink to &quot;4.3 基建&quot;">​</a></h3><p>早期建筑优先级（一般顺序）：<strong>粮仓 → 纪念碑 → 图书馆 → 神社</strong></p><ul><li><strong>纪念碑</strong>：+2 文化，加速扩地和政策解锁。</li><li><strong>粮仓</strong>：+食物，间接提升产能（需 ≥2 粮地块，且快乐非负）。</li><li><strong>神社</strong>：开启万神殿/宗教，但需 135 信仰才能出大先知，回报周期长。</li><li><strong>图书馆</strong>：提升科研，早期战争中作用有限，优势局可考虑。</li></ul><blockquote><p>建筑顺序可根据局势调整，如快乐不足时优先纪念碑。</p></blockquote><h3 id="_4-4-政策" tabindex="-1">4.4 政策 <a class="header-anchor" href="#_4-4-政策" aria-label="Permalink to &quot;4.4 政策&quot;">​</a></h3><p>三大路线：</p><ul><li><strong>传统</strong>：当前环境较弱，不推荐。</li><li><strong>自主</strong>：适合领土广阔者，提升城市发展速度。</li><li><strong>荣誉</strong>：军事爆发极强，尤其在力量悬殊时近乎无敌。</li></ul><p>黑科技流派：荣誉转自主</p><ul><li>适用：小地图 + 有野蛮人。</li><li>效果：保留荣誉 100% 爆发力 + 自主 75% 种田能力。</li><li>补充手段：建纪念碑 或 选“天空之神”加速文化。</li></ul><h2 id="_5-中期种田" tabindex="-1">5 中期种田 <a class="header-anchor" href="#_5-中期种田" aria-label="Permalink to &quot;5 中期种田&quot;">​</a></h2><h3 id="_5-1-基建" tabindex="-1">5.1 基建 <a class="header-anchor" href="#_5-1-基建" aria-label="Permalink to &quot;5.1 基建&quot;">​</a></h3><p>僵持期加强建筑以增加筹码：</p><ul><li><strong>马厩</strong>： <ul><li>+牛/马/羊地块产能</li><li>骑兵建造 +15% 产能</li></ul></li><li><strong>石工坊</strong>： <ul><li>+1 快乐 +1 产能</li><li>+大理石/花岗岩地块产能</li></ul></li><li><strong>马戏场</strong>： <ul><li>需马或象牙</li><li>+2 快乐，造价低于竞技场（快速模式便宜 17 产能）</li></ul></li></ul><blockquote><p>优先解锁与城市资源匹配的建筑。</p></blockquote><ul><li><strong>兵营</strong>： <ul><li>无内政收益，但新兵 +15 经验</li><li>维护费 1 金</li><li>适合：内政稳定 + 需精锐近战（如对抗远程主力）</li><li>地形适配：平原/崎岖地形决战点可针对性出晋升</li></ul></li></ul><h3 id="_5-2-修路" tabindex="-1">5.2 修路 <a class="header-anchor" href="#_5-2-修路" aria-label="Permalink to &quot;5.2 修路&quot;">​</a></h3><p>道路优势：</p><ol><li><strong>军事支援迅速</strong>：单位快速调动，突破地形限制（如战车在丘陵仍可移动射击）。</li><li><strong>贸易收益</strong>：连接首都与其他城市，提供金钱。</li></ol><blockquote><p>注意：每格道路维护费 1 金。<br> 最短连接需 3 格（因城市 3 格内不能建城），故分城至少需 3 人口才能覆盖维护费。</p></blockquote><p><strong>结论</strong>：早期不宜建太分散的城市。</p><h3 id="_5-3-奇观" tabindex="-1">5.3 奇观 <a class="header-anchor" href="#_5-3-奇观" aria-label="Permalink to &quot;5.3 奇观&quot;">​</a></h3><p>推荐：</p><ul><li>大图书馆</li><li>弓庙</li><li>佩特拉</li><li>空中花园</li></ul><h2 id="_6-结合时势走棋" tabindex="-1">6 结合时势走棋 <a class="header-anchor" href="#_6-结合时势走棋" aria-label="Permalink to &quot;6 结合时势走棋&quot;">​</a></h2><p>内政科技解锁需综合考量：</p><ol><li><p><strong>资源匹配</strong>：</p><ul><li>马/牛/羊多 → 优先骑术 + 马厩</li><li>猎场/奢侈多 → 优先捕猎 + 开发</li></ul></li><li><p><strong>地形适配</strong>：</p><ul><li>草原 → 骑术/马厩</li><li>森林 → 林业/伐木场</li></ul></li><li><p><strong>局势判断</strong>：</p><ul><li>控制 &gt; 科技 &gt; 内政</li><li>劣势 → 考虑军事翻盘</li><li>优势 → 专注内政积累</li></ul></li></ol><blockquote><p>避免在错误地形研究无关科技，造成资源浪费。</p></blockquote><h2 id="_7-实战演练" tabindex="-1">7 实战演练 <a class="header-anchor" href="#_7-实战演练" aria-label="Permalink to &quot;7 实战演练&quot;">​</a></h2><h3 id="_7-1-过程" tabindex="-1">7.1 过程 <a class="header-anchor" href="#_7-1-过程" aria-label="Permalink to &quot;7.1 过程&quot;">​</a></h3><p><strong>对局</strong>：恶 vs 陌生的云 祭楼源（1v1 极小单挑）</p><ul><li>开局资源富饶，粮地多，但奢侈资源需历法科技，快乐不足。 <img src="'+d+'" alt=""></li><li>恶选择<strong>勇士起手</strong>，增强地图控制。 <img src="'+h+'" alt=""></li><li>遇敌方勇士对峙，敌方斥候探图。</li><li>恶判断下方资源差、支援难，放弃，转而<strong>绕后限制敌方移民</strong>。 <img src="'+u+'" alt=""></li><li>发现上方资源尚可、支援便利，决定在此建分城，用双勇士压制抢地。</li><li>成功限制敌方移民 2 回合，己方移民安全抵达。</li><li>因山脉阻隔，军事推进困难，转为<strong>双工砍树爆内政</strong>。</li><li>但奢侈资源差，粮仓收益低，内政受限，遂转<strong>军事速攻</strong>，科技走复合弓。</li><li>虽产能领先（敌方贪粮仓亏产），但因<strong>山脉+河流阻隔</strong>，速攻失败。</li><li>敌方利用地形拖延，成功爆兵反制。 <img src="'+p+'" alt=""><img src="'+g+'" alt=""><img src="'+c+'" alt=""><img src="'+_+'" alt=""><img src="'+b+'" alt=""><img src="'+q+'" alt=""></li></ul><h3 id="_7-2-复盘" tabindex="-1">7.2 复盘 <a class="header-anchor" href="#_7-2-复盘" aria-label="Permalink to &quot;7.2 复盘&quot;">​</a></h3><ul><li><strong>恶</strong>：节奏几乎全优，产能领先，但地形限制导致军事/内政均无法施展，无奈 GG。</li><li><strong>敌方</strong>：地形理解出色，从选址开始就立于不败之地，虽冒险贪粮仓，但地形为其争取时间，最终获胜。</li></ul><h2 id="_8-补充" tabindex="-1">8 补充 <a class="header-anchor" href="#_8-补充" aria-label="Permalink to &quot;8 补充&quot;">​</a></h2><h3 id="_8-1-荣誉卡产" tabindex="-1">8.1 荣誉卡产 <a class="header-anchor" href="#_8-1-荣誉卡产" aria-label="Permalink to &quot;8.1 荣誉卡产&quot;">​</a></h3><p>荣誉政策左一分支：<strong>近战单位建造 +15% 产能</strong>。</p><p>Unciv 产能计算采用 <strong>“四舍五入”</strong>：</p><ul><li>4 产能 → 3.4 → 显示 3，实际省 0.6</li><li>10 产能 → 8.5 → 显示 9，省 1.5</li><li>17 产能 → 14.45 → 显示 15，省 2</li></ul><blockquote><p>可用于极限控产，提升效率。</p></blockquote><h3 id="_8-2-回档-save-load" tabindex="-1">8.2 回档（-save load） <a class="header-anchor" href="#_8-2-回档-save-load" aria-label="Permalink to &quot;8.2 回档（-save load）&quot;">​</a></h3><ul><li>对当前回合操作不满意？可回档重来。</li><li>适用于探图，将<strong>概率性技能</strong>（如印加投石手、德国抢蛮寨）变为必然触发。</li><li><strong>注意</strong>：伤害量无法通过回档改变。</li></ul><h3 id="_8-3-砍树" tabindex="-1">8.3 砍树 <a class="header-anchor" href="#_8-3-砍树" aria-label="Permalink to &quot;8.3 砍树&quot;">​</a></h3><ul><li>两个工人同时砍同一座城市的两棵树，<strong>只触发一次产能爆发</strong>。</li></ul><h3 id="_8-4-决策" tabindex="-1">8.4 决策 <a class="header-anchor" href="#_8-4-决策" aria-label="Permalink to &quot;8.4 决策&quot;">​</a></h3><p>面对特殊地形/情况，<strong>切勿套公式</strong>。</p><ul><li>分析地形特点（山地防高但移速慢，平原快但无屏障）。</li><li>根据实时信息（如胜利面板）调整策略。</li><li>避免“盲目感”：迷茫时应暂停，明确目标再行动。</li><li>若局势确实无法挽回，<strong>及时止损重开</strong>也是智慧。</li></ul><blockquote><p>灵活应变 + 独立思考 = 立于不败之地。</p></blockquote>',140)])])}const A=m(P,[["render",v]]);export{$ as __pageData,A as default};
